import { describe, expect, it } from 'vitest';
import { fulfillmentBadge } from './Solution';

/**
 * 断言由 gen.py 里同一个 badge() 模型生成，不手抄。
 * 契约型用例断言到消息：四条"都该抛错"的用例否则会被收敛成同一条代码路径。
 */
describe('fulfillmentBadge：48 小时承诺 × 缺货三态 × 风控打标', () => {
  it("基线：付款后 30 小时未发货 ⇒ 待发货，进队列，不赔付", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": -1, "riskControlStatus": 0, "confirmStatus": 0, "groupStatus": 0, "paidAtSec": 0, "shippedAtSec": null, "nowSec": 108000})).toEqual({"level": "ok", "label": "待发货", "payoutEligible": false, "inShipQueue": true});
  });
  it("缺货待处理：既判违约又不许进发货队列", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": 0, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": 0, "shippedAtSec": null, "nowSec": 3600})).toEqual({"level": "breach", "label": "缺货待处理 · 触发赔付", "payoutEligible": true, "inShipQueue": false});
  });
  it("审核中优先于缺货：赔付与队列都要关停", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": 0, "riskControlStatus": 1, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": 0, "shippedAtSec": null, "nowSec": 3600})).toEqual({"level": "blocked", "label": "审核中 · 不进发货队列", "payoutEligible": false, "inShipQueue": false});
  });
  it("边界：正好 48 小时不算超时（严格大于才违约）", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": -1, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": 1000, "shippedAtSec": null, "nowSec": 173800})).toEqual({"level": "watch", "label": "临近 48 小时", "payoutEligible": false, "inShipQueue": true});
  });
  it("边界：48 小时后再多一秒 ⇒ 违约，且已经发货的单也要被追认", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": -1, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": 0, "shippedAtSec": 172801, "nowSec": 200000})).toEqual({"level": "breach", "label": "已发货但超 48 小时", "payoutEligible": true, "inShipQueue": false});
  });
  it("团失败：不赔付（钱要退不是要赔），但要进\"待回补\"视野", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": -1, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 2, "paidAtSec": 0, "shippedAtSec": null, "nowSec": 3600})).toEqual({"level": "watch", "label": "团失败 · 待回补", "payoutEligible": false, "inShipQueue": false});
  });
  it("退化：已取消的单最优先，缺货标记一概不许覆盖它", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": 0, "riskControlStatus": 1, "confirmStatus": 2, "groupStatus": 1, "paidAtSec": 0, "shippedAtSec": null, "nowSec": 999999})).toEqual({"level": "muted", "label": "已取消", "payoutEligible": false, "inShipQueue": false});
  });
  it("临近超时：42 小时未发货 ⇒ watch，仍在队列里", () => {
    expect(fulfillmentBadge({"stockOutHandleStatus": -1, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": 0, "shippedAtSec": null, "nowSec": 155000})).toEqual({"level": "watch", "label": "临近 48 小时", "payoutEligible": false, "inShipQueue": true});
  });
  it("非法：未知的缺货处理状态", () => {
    expect(() => fulfillmentBadge({"stockOutHandleStatus": 7, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": 0, "shippedAtSec": null, "nowSec": 1} as never)).toThrow("unknown stockOutHandleStatus");
  });
  it("非法：时间戳为负", () => {
    expect(() => fulfillmentBadge({"stockOutHandleStatus": -1, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": -5, "shippedAtSec": null, "nowSec": 1} as never)).toThrow("timestamps must be non-negative integers");
  });
  it("非法：发货时间类型不对（既不是 null 也不是非负整数）", () => {
    expect(() => fulfillmentBadge({"stockOutHandleStatus": -1, "riskControlStatus": 0, "confirmStatus": 1, "groupStatus": 1, "paidAtSec": 0, "shippedAtSec": "123", "nowSec": 1} as never)).toThrow("shippedAtSec must be null or a non-negative integer");
  });
  it("非法：整行是 null", () => {
    expect(() => fulfillmentBadge(null as never)).toThrow("row must be an object");
  });
});

